def sort_merge_join(A, B, key):
    A, B = sorted(A, key=key), sorted(B, key=key)  # 정렬
    i = j = 0
    out = []
    while i < len(A) and j < len(B):  # 병합 단계
        ka, kb = key(A[i]), key(B[j])
        if ka < kb:
            i += 1
        elif ka > kb:
            j += 1
        else:  # 같은 키 그룹끼리 모두 결합
            j_end = j
            while j_end < len(B) and key(B[j_end]) == ka:
                j_end += 1
            while i < len(A) and key(A[i]) == ka:
                for b in B[j:j_end]:
                    out.append((A[i], b))
                i += 1
            j = j_end
    return out
